// atlas2d: the owner's sprite-sheet atlas, and one texture per sprite.
//
// Its own module because BOTH `props.js` (the loot pickups) and `props/props2d.js` (the decor) draw
// from it, and props2d.js already borrows the billboard builder from props.js — putting the atlas in
// either of them makes an import cycle.
//
// The atlas and its map are generated by `tools/props2d-import/` (slice, then pack); a sprite's rect is
// in the atlas's own pixels, at the art's NATIVE resolution — the packer detects art handed over at 2x
// or 16x and resamples it back down, so `w`/`h` here are real art pixels and can be read as texels.
import * as THREE from 'three';
import { PROPS2D, PROPS2D_ATLAS } from '../../assets/props2d/map.js';

const URL_ATLAS = new URL('../../assets/props2d/atlas.png', import.meta.url).href;
let atlas = null;
const texCache = new Map();

/** The shared atlas texture, loaded once. Nothing waits for it: a sprite appears when it lands. */
export function atlasTexture() {
  if (atlas) return atlas;
  atlas = new THREE.TextureLoader().load(URL_ATLAS);
  atlas.colorSpace = THREE.SRGBColorSpace;
  atlas.magFilter = THREE.NearestFilter;
  atlas.minFilter = THREE.NearestFilter;
  atlas.generateMipmaps = false;
  return atlas;
}

/** One sprite of the atlas as its own texture (a clone sharing the image, with its own window). */
export function spriteTexture(name) {
  if (texCache.has(name)) return texCache.get(name);
  const r = PROPS2D[name];
  if (!r) return null;
  const t = atlasTexture().clone();
  t.needsUpdate = true;
  t.repeat.set(r.w / PROPS2D_ATLAS.w, r.h / PROPS2D_ATLAS.h);
  t.offset.set(r.x / PROPS2D_ATLAS.w, 1 - (r.y + r.h) / PROPS2D_ATLAS.h);
  texCache.set(name, t);
  return t;
}

/** The sprite's rect, or null. */
export function spriteRect(name) { return PROPS2D[name] || null; }

/**
 * The size in TEXELS for a sprite asked to stand `tiles` wide. The sheet's art is not drawn at this
 * game's 32-texels-a-tile, so every caller states the width it wants in tiles and the height follows
 * the art's own proportions.
 */
export function spriteTexels(name, tiles, texelsPerTile = 32) {
  const r = PROPS2D[name];
  if (!r) return null;
  const w = tiles * texelsPerTile;
  return { w, h: w * (r.h / r.w) };
}

/** How hard the room lights a sprite lying on the floor (see props2d.js SHEET_TUNE). */
const GROUND_ALBEDO = 0.62;

/**
 * THE OTHER WAY TO PUT A SPRITE IN THE WORLD: flat on the floor, as a piece of the board rather than a
 * standee (owner, 2026-09-20: "attach it as a texture to a 3d-square, and position that square on the
 * ground in the same coordinates you would for any prop").
 *
 * It is a plain quad in the FLOOR PLANE at the tile's own coordinates, `tiles` wide, sized from the art's
 * proportions. Nothing billboards, nothing snaps, nothing is sized from the camera: it is geometry in the
 * world like the flagstones under it, so it holds still exactly as well as they do and turns with the
 * camera because it is lying there. Straight down it reads face-on; at a tilt it foreshortens like a card
 * on a table, which is the honest trade.
 * @param {string} name a sprite in the sheet atlas
 * @param {{tiles?:number, y?:number, facing?:string}} [o]
 */
export function buildGroundSprite(name, o = {}) {
  const rect = spriteRect(name), tex = spriteTexture(name);
  if (!rect || !tex) return null;
  const w = o.tiles ?? 0.9, h = w * (rect.h / rect.w);
  const g = new THREE.Group();
  const geo = new THREE.PlaneGeometry(w, h).rotateX(-Math.PI / 2);
  const mat = new THREE.MeshStandardMaterial({
    map: tex, transparent: false, alphaTest: 0.5, roughness: 1, metalness: 0,
    emissiveMap: tex, emissive: new THREE.Color(0xffffff), emissiveIntensity: 0.12,
    color: new THREE.Color(GROUND_ALBEDO, GROUND_ALBEDO, GROUND_ALBEDO),
  });
  const m = new THREE.Mesh(geo, mat);
  m.position.y = o.y ?? 0.02;                    // a hair off the flagstone, like a floor decal
  m.rotation.y = { n: Math.PI, e: -Math.PI / 2, s: 0, w: Math.PI / 2 }[o.facing || 's'] || 0;
  m.receiveShadow = false; m.castShadow = false;
  g.add(m);
  g.userData.decor = { type: name, variant: 0, facing: o.facing || 's', cls: 'decal', sheet: name, ground: true };
  return g;
}

